# 联合与交叉 — 类型的「或」与「且」

## 联合类型 (Union) — 或者是A，或者是B

联合类型用 `|` 连接，就像餐厅的「套餐A或套餐B」——你只能选一个：
```typescript
let id: string | number;
id = "abc";   // 合法
id = 123;    // 也合法
// id = true; // 报错！
```

## 类型守卫 — 区分联合类型

面对联合类型，TypeScript 不知道当前是哪种类型，需要你用类型守卫来「验明正身」：
```typescript
function process(value: string | number): string {
    if (typeof value === "string") {
        return value.toUpperCase();  // TypeScript 知道这里是 string
    }
    return value.toFixed(2);        // TypeScript 知道这里是 number
}
```

## 交叉类型 (Intersection) — 既是A，又是B

交叉类型用 `&` 连接，就像一个人同时拥有两个身份——既是员工又是学生：
```typescript
interface Employee {
    employeeId: string;
}

interface Student {
    studentId: string;
}

type WorkingStudent = Employee & Student;

let person: WorkingStudent = {
    employeeId: "E001",
    studentId: "S001"
};
```

## 练习
编写函数 `formatInput(input: string | number)`，如果是字符串则转大写，如果是数字则保留两位小数返回字符串。

starter_code:
function formatInput(input: string | number): string {
    // 根据类型格式化输入
    return "";
}

solution_code:
function formatInput(input: string | number): string {
    if (typeof input === "string") {
        return input.toUpperCase();
    }
    return input.toFixed(2);
}

starter_code:
function getSeason(month: number): "春" | "夏" | "秋" | "冬" {
    // 根据月份返回季节
    return "春";
}

solution_code:
function getSeason(month: number): "春" | "夏" | "秋" | "冬" {
    if (month >= 3 && month <= 5) return "春";
    if (month >= 6 && month <= 8) return "夏";
    if (month >= 9 && month <= 11) return "秋";
    return "冬";
}

starter_code:
function getLength(value: unknown): number {
    // 使用 as 断言获取长度
    return 0;
}

solution_code:
function getLength(value: unknown): number {
    if (typeof value === "string") {
        return (value as string).length;
    }
    if (Array.isArray(value)) {
        return (value as unknown[]).length;
    }
    return 0;
}

