# 模块系统 — 代码的「房间划分」

大型项目就像一栋大楼，模块就是不同的房间——每个房间有自己的功能，通过门（export/import）连接。

## ES Module — 标准模块系统

```typescript
// math.ts — 导出
export function add(a: number, b: number): number {
    return a + b;
}
export const PI = 3.14;

// app.ts — 导入
import { add, PI } from "./math";
console.log(add(1, 2));  // 3
```

默认导出：
```typescript
// logger.ts
export default function log(msg: string): void {
    console.log(msg);
}

// app.ts
import log from "./logger";
```

## 命名空间 — 内部模块

命名空间就像在一个大房间里用隔板划出小区域：
```typescript
namespace Utils {
    export function format(str: string): string {
        return str.trim().toLowerCase();
    }
}

Utils.format("  Hello  ");  // "hello"
```

## 声明合并 — 接口的特殊能力

同名接口会自动合并，就像两个人各自写了一部分合同，最终合并成完整版：
```typescript
interface Config {
    host: string;
}
interface Config {
    port: number;
}
// 合并后: { host: string; port: number }
```

命名空间也可以与类、函数合并：
```typescript
class Album {
    label: string = "";
}
namespace Album {
    export const defaultLabel = "Unknown";
}
```

## 练习
编写函数 `createModuleInfo(name: string, version: string)`，返回格式化的模块信息字符串 `"{name}@{version}"`。

starter_code:
// 模拟 ES Module 导出/导入模式

// 定义数学工具模块的导出接口
interface MathModule {
    add(a: number, b: number): number;
    multiply(a: number, b: number): number;
    PI: number;
}

// TODO: 创建并导出 math 模块对象
function createMathModule(): MathModule {
    // 返回符合 MathModule 接口的对象
    return { add: (a, b) => 0, multiply: (a, b) => 0, PI: 0 };
}

// TODO: 解构导入模块成员
function calcArea(radius: number): number {
    // 使用模块的 PI 和 multiply 计算圆面积
    return 0;
}

solution_code:
interface MathModule {
    add(a: number, b: number): number;
    multiply(a: number, b: number): number;
    PI: number;
}

function createMathModule(): MathModule {
    const PI = 3.14159;
    return {
        add: (a: number, b: number): number => a + b,
        multiply: (a: number, b: number): number => a * b,
        PI,
    };
}

function calcArea(radius: number): number {
    const { PI, multiply } = createMathModule();
    return multiply(PI, multiply(radius, radius));
}

